var puppeteer = require("puppeteer");
var path = require("path");

function formatTimestamp(ts) {
    if (!ts) return "N/A";
    var d = new Date(ts);
    var yyyy = d.getFullYear();
    var mm   = String(d.getMonth() + 1).padStart(2, "0");
    var dd   = String(d.getDate()).padStart(2, "0");
    var hh   = String(d.getHours()).padStart(2, "0");
    var min  = String(d.getMinutes()).padStart(2, "0");
    var ss   = String(d.getSeconds()).padStart(2, "0");
    return yyyy + "-" + mm + "-" + dd + "T" + hh + ":" + min + ":" + ss + "Z";
}

function generateHTML(audits) {
    return `
    <!DOCTYPE html>
    <html lang="en">
    <head>
      <meta charset="UTF-8">
      <title>Audit Report</title>
      <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        h1 { text-align: center; }
        table { width: 100%; border-collapse: collapse; margin-top: 20px; }
        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
        th { background-color: #f4f4f4; }
        tr:nth-child(even) { background-color: #f9f9f9; }
      </style>
    </head>
    <body>
      <h1>Audit Report</h1>
      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Timestamp</th>
            <th>Operation</th>
            <th>Resource ID</th>
            <th>User ID</th>
          </tr>
        </thead>
        <tbody>
          ${audits.map(function(audit) {
            return `
              <tr>
                <td>${audit.id}</td>
                <td>${formatTimestamp(audit.timestamp)}</td>
                <td>${audit.operation}</td>
                <td>${audit.resourceId !== null && audit.resourceId !== undefined ? audit.resourceId : "N/A"}</td>
                <td>${audit.userId || "N/A"}</td>
              </tr>
            `;
          }).join("")}
        </tbody>
      </table>
    </body>
    </html>
    `;
}

